insert into terms (service, type, lang, version, body, required, effective_at, created_at, updated_at) values
('HONEY_DROPS', 'SERVICE', 'ko', '2026-08', $json${"title":"꿀방울 이용약관","sections":[{"heading":"제1조 (목적)","blocks":[{"type":"p","text":"이 약관은 Honey Salt Love가 제공하는 꿀방울 서비스의 이용에 관한 사항을 정합니다."}]},{"heading":"제2조 (서비스 내용)","blocks":[{"type":"p","text":"꿀방울은 수면 준비와 생활습관 형성을 돕기 위한 미션, 활동, 기록, 타이머 및 알림 기능을 제공합니다."}]},{"heading":"제3조 (기록 저장 및 활동 공유)","blocks":[{"type":"p","text":"사용자가 직접 작성한 기록(감정 기록, 생각, 감사, 목표 등)과 공유하지 않은 사용자 활동은 사용자의 기기에 저장됩니다."},{"type":"p","text":"사용자가 활동 공유를 선택한 경우에만 해당 활동의 이름, 관련 링크, 설명 및 해당 미션이 운영자에게 전송됩니다."},{"type":"p","text":"운영자는 사용자가 공유하지 않은 활동과 직접 작성한 기록의 내용을 확인할 수 없습니다."},{"type":"p","text":"앱 개선을 위한 이용 기록은 기기 식별자와 함께 서버에 저장되며, 자세한 내용은 개인정보처리방침에서 확인할 수 있습니다."},{"type":"p","text":"앱을 삭제하거나 기기를 변경·분실하면 기기에 저장된 기록이 사라질 수 있습니다."}]},{"heading":"제4조 (서비스 이용)","blocks":[{"type":"p","text":"이용자는 서비스를 정상적인 용도로 이용해야 하며, 서비스 운영을 방해하거나 콘텐츠를 무단으로 복제·배포해서는 안 됩니다."}]},{"heading":"제5조 (서비스 변경 및 중단)","blocks":[{"type":"p","text":"서비스의 일부 기능은 개선, 점검 또는 운영상의 필요에 따라 변경되거나 중단될 수 있습니다."},{"type":"p","text":"중요한 변경 사항은 앱 또는 홈페이지를 통해 안내합니다."}]},{"heading":"제6조 (주의사항)","blocks":[{"type":"p","text":"꿀방울은 생활습관 관리를 돕는 서비스이며 의료적 진단이나 치료, 전문적인 심리상담을 제공하지 않습니다."},{"type":"p","text":"건강상의 문제가 있거나 전문적인 도움이 필요한 경우 의료기관 또는 전문가와 상담해 주세요."}]},{"heading":"제7조 (기록의 손실)","blocks":[{"type":"p","text":"기기 고장, 앱 삭제, 기기 변경, 운영체제 문제 또는 이용자의 부주의로 기기에 저장된 기록이 사라질 수 있습니다."},{"type":"p","text":"운영자는 관련 법령이 허용하는 범위에서 이러한 기록의 손실에 대한 책임을 부담하지 않습니다."}]},{"heading":"제8조 (지식재산권)","blocks":[{"type":"p","text":"꿀방울에 포함된 글, 이미지, 디자인 및 프로그램의 저작권과 지식재산권은 Honey Salt Love에 있습니다."},{"type":"p","text":"운영자의 허락 없이 이를 복제, 수정, 배포 또는 상업적으로 이용할 수 없습니다."}]},{"heading":"제9조 (약관 변경)","blocks":[{"type":"p","text":"이 약관은 서비스 변경 또는 관련 법령에 따라 수정될 수 있습니다."},{"type":"p","text":"중요한 변경 사항은 시행 전에 앱 또는 홈페이지를 통해 안내합니다."}]},{"heading":"제10조 (고객지원 및 문의)","blocks":[{"type":"p","text":"서비스 이용에 관한 문의, 오류 신고 및 공유 활동 삭제 요청은 고객지원 페이지에서 접수할 수 있습니다."},{"type":"link","to":"support","text":"고객지원 및 문의"}]}]}$json$, true, '2026-07-31T15:00:00Z', now(), now()),
('HONEY_DROPS', 'SERVICE', 'en', '2026-08', $json${"title":"Honey Drops Terms of Service","sections":[{"heading":"Article 1 (Purpose)","blocks":[{"type":"p","text":"These Terms set out the conditions for using Honey Drops, a service provided by Honey Salt Love."}]},{"heading":"Article 2 (Service)","blocks":[{"type":"p","text":"Honey Drops provides missions, activities, records, timers, and notifications designed to support sleep preparation and healthy daily habits."}]},{"heading":"Article 3 (Record Storage and Activity Sharing)","blocks":[{"type":"p","text":"Records you write yourself (emotion logs, thoughts, gratitude, goals, and the like) and user-created activities that have not been shared are stored on the user’s device."},{"type":"p","text":"Only when a user chooses to share an activity are its name, related link, description, and related mission transmitted to the operator."},{"type":"p","text":"The operator cannot access user-created records or activities that the user has not chosen to share."},{"type":"p","text":"Usage records kept to improve the app are stored on the server together with a device identifier; see the Privacy Policy for details."},{"type":"p","text":"Records stored on the device may be lost if the app is deleted or the device is changed, lost, or reset."}]},{"heading":"Article 4 (Use of the Service)","blocks":[{"type":"p","text":"Users must use the service for its intended purposes and must not interfere with its operation or reproduce or distribute its content without permission."}]},{"heading":"Article 5 (Changes and Suspension)","blocks":[{"type":"p","text":"Some features may be changed or suspended for improvement, maintenance, or operational reasons."},{"type":"p","text":"Important changes will be announced through the app or website."}]},{"heading":"Article 6 (Important Notice)","blocks":[{"type":"p","text":"Honey Drops supports healthy daily habits and does not provide medical diagnosis, treatment, or professional psychological counseling."},{"type":"p","text":"Users with health concerns or who require professional assistance should consult a medical institution or qualified professional."}]},{"heading":"Article 7 (Loss of Records)","blocks":[{"type":"p","text":"Records stored on the device may be lost because of device failure, app deletion, device replacement, operating system issues, or user error."},{"type":"p","text":"To the extent permitted by applicable law, the operator is not responsible for such loss of records."}]},{"heading":"Article 8 (Intellectual Property)","blocks":[{"type":"p","text":"The text, images, designs, software, and other content included in Honey Drops are owned by Honey Salt Love."},{"type":"p","text":"They may not be reproduced, modified, distributed, or used commercially without permission from the operator."}]},{"heading":"Article 9 (Changes to These Terms)","blocks":[{"type":"p","text":"These Terms may be revised due to service changes or applicable laws."},{"type":"p","text":"Important changes will be announced through the app or website before they take effect."}]},{"heading":"Article 10 (Support and Contact)","blocks":[{"type":"p","text":"Service inquiries, error reports, and requests to delete shared activities may be submitted through the support page."},{"type":"link","to":"support","text":"Support & Contact"}]}]}$json$, true, '2026-07-31T15:00:00Z', now(), now()),
('HONEY_DROPS', 'SERVICE', 'ja', '2026-08', $json${"title":"ハニードロップス 利用規約","sections":[{"heading":"第1条（目的）","blocks":[{"type":"p","text":"本規約は、Honey Salt Love が提供する ハニードロップス サービスの利用に関する事項を定めます。"}]},{"heading":"第2条（サービス内容）","blocks":[{"type":"p","text":"ハニードロップス は、睡眠の準備と生活習慣づくりを助けるためのミッション、活動、記録、タイマー、通知の機能を提供します。"}]},{"heading":"第3条（記録の保存および活動の共有）","blocks":[{"type":"p","text":"利用者が自ら作成した記録（感情の記録、考え、感謝、目標など）および共有していない利用者の活動は、利用者の端末に保存されます。"},{"type":"p","text":"利用者が活動の共有を選択した場合にのみ、その活動の名称、関連リンク、説明、該当ミッションが運営者に送信されます。"},{"type":"p","text":"運営者は、利用者が共有していない活動および自ら作成した記録の内容を確認することはできません。"},{"type":"p","text":"アプリ改善のための利用記録は端末識別子とともにサーバーに保存されます。詳細はプライバシーポリシーをご確認ください。"},{"type":"p","text":"アプリを削除したり、端末を変更・紛失したりすると、端末に保存された記録が失われることがあります。"}]},{"heading":"第4条（サービスの利用）","blocks":[{"type":"p","text":"利用者はサービスを本来の用途で利用しなければならず、サービスの運営を妨げたり、コンテンツを無断で複製・配布したりしてはなりません。"}]},{"heading":"第5条（サービスの変更および中断）","blocks":[{"type":"p","text":"サービスの一部の機能は、改善、点検、または運営上の必要に応じて変更または中断されることがあります。"},{"type":"p","text":"重要な変更事項は、アプリまたはホームページを通じてお知らせします。"}]},{"heading":"第6条（注意事項）","blocks":[{"type":"p","text":"ハニードロップス は生活習慣の管理を助けるサービスであり、医療的な診断や治療、専門的な心理カウンセリングを提供するものではありません。"},{"type":"p","text":"健康上の問題がある場合や専門的な支援が必要な場合は、医療機関または専門家にご相談ください。"}]},{"heading":"第7条（記録の消失）","blocks":[{"type":"p","text":"端末の故障、アプリの削除、端末の変更、OS の問題、または利用者の不注意により、端末に保存された記録が失われることがあります。"},{"type":"p","text":"運営者は、関連法令が認める範囲において、このような記録の消失について責任を負いません。"}]},{"heading":"第8条（知的財産権）","blocks":[{"type":"p","text":"ハニードロップス に含まれる文章、画像、デザイン、プログラムの著作権および知的財産権は Honey Salt Love に帰属します。"},{"type":"p","text":"運営者の許可なく、これらを複製、修正、配布、または商業的に利用することはできません。"}]},{"heading":"第9条（規約の変更）","blocks":[{"type":"p","text":"本規約は、サービスの変更または関連法令に応じて改定されることがあります。"},{"type":"p","text":"重要な変更事項は、施行前にアプリまたはホームページを通じてお知らせします。"}]},{"heading":"第10条（サポートおよびお問い合わせ）","blocks":[{"type":"p","text":"サービス利用に関するお問い合わせ、不具合の報告、共有した活動の削除依頼は、サポートページから受け付けています。"},{"type":"link","to":"support","text":"サポート・お問い合わせ"}]}]}$json$, true, '2026-07-31T15:00:00Z', now(), now()),
('HONEY_DROPS', 'PRIVACY', 'ko', '2026-08', $json${"title":"꿀방울 개인정보처리방침","intro":"Honey Salt Love는 이용자의 정보를 안전하게 보호하며, 꿀방울에서 처리하는 정보를 다음과 같이 안내합니다.","sections":[{"heading":"1. 사용자가 작성한 기록","blocks":[{"type":"p","text":"사용자가 직접 작성한 기록(감정 기록, 생각, 감사, 목표 등)과 공유하지 않은 사용자 활동은 사용자의 기기에 저장됩니다."},{"type":"p","text":"운영자는 이를 확인할 수 없습니다."},{"type":"p","text":"앱을 삭제하거나 기기를 변경·분실하면 기기에 저장된 기록이 사라질 수 있습니다."}]},{"heading":"2. 앱 개선을 위해 서버에 저장하는 정보","blocks":[{"type":"p","text":"꿀방울은 앱 개선을 위해 기기 식별자와 함께 날짜별 이용 기록을 서버에 저장합니다."},{"type":"p","text":"기기를 구분하기 위해 다음 식별자를 사용합니다. 이름, 연락처 등 이용자를 직접 알아볼 수 있는 정보는 포함하지 않습니다."},{"type":"list","items":["기기 식별자 (Android ID)","앱이 처음 실행될 때 만든 임의의 식별자","익명 인증 식별자"]},{"type":"p","text":"함께 저장되는 이용 기록은 다음과 같습니다."},{"type":"list","items":["그날 선택한 감정","꿀방울 레벨과 별점수","실행한 미션과 활동","도움됨으로 표시한 항목","하루 사용 시간","앱 버전, 언어, 테마 설정"]},{"type":"p","text":"광고 식별자는 수집하지 않으며, 이용자가 직접 작성한 글(감정 기록, 생각, 감사, 목표 등)은 서버로 전송되지 않습니다."},{"type":"p","text":"서버로 전송되는 정보는 전송 구간에서 암호화됩니다."}]},{"heading":"3. 사용자가 공유한 활동","blocks":[{"type":"p","text":"이용자가 활동 등록 화면에서 공유를 선택하면 다음 정보가 운영자에게 전송됩니다."},{"type":"list","items":["활동 이름","관련 링크","활동 설명","해당 미션"]},{"type":"p","text":"활동 공유는 선택 사항이며, 공유하지 않아도 활동을 등록하고 사용할 수 있습니다."},{"type":"p","text":"공유된 활동은 다른 이용자에게 추천할 활동을 검토하고 서비스를 개선하기 위해 사용하며, 삭제를 원하는 경우 고객지원 페이지를 통해 요청할 수 있습니다."}]},{"heading":"4. 이용 목적","blocks":[{"type":"p","text":"처리된 정보는 다음 목적으로만 사용합니다."},{"type":"list","items":["이용 현황 확인","도움이 되는 활동 분석","공유 활동 검토 및 추천","기능 및 서비스 개선","오류 확인"]}]},{"heading":"5. 보유 및 파기","blocks":[{"type":"p","text":"이용 기록은 기기 식별자와 날짜를 기준으로 저장되며, 저장된 날부터 24개월이 지나면 자동으로 삭제됩니다."},{"type":"p","text":"앱에서 초기화를 실행하시면 휴대폰에 저장된 내용은 즉시 삭제됩니다. 서버에 저장된 기록은 즉시 삭제되지 않으며, 삭제 예정일이 초기화한 날부터 24개월 뒤로 다시 지정되어 그날 자동으로 삭제됩니다."},{"type":"p","text":"그 전에 삭제를 원하시면 고객지원으로 요청해 주세요."},{"type":"p","text":"공유된 활동은 서비스 개선 및 추천에 필요한 기간 동안 보관합니다."},{"type":"p","text":"이용 목적이 달성되거나 해당 정보가 필요하지 않게 된 경우 지체 없이 삭제합니다."}]},{"heading":"6. 처리위탁","blocks":[{"type":"p","text":"꿀방울은 서비스 운영을 위해 Google 의 Firebase 를 이용하며, 다음 업무를 위탁합니다."},{"type":"list","items":["Firebase Analytics — 이용 통계","Cloud Firestore — 이용 기록 저장","Firebase Crashlytics — 오류 수집","Firebase Authentication — 익명 인증"]},{"type":"p","text":"해당 정보는 Google 의 서버에 저장되며, 국외에 위치할 수 있습니다."}]},{"heading":"7. 제3자 제공","blocks":[{"type":"p","text":"Honey Salt Love는 이용 정보를 판매하거나 광고 목적으로 제공하지 않습니다."},{"type":"p","text":"법령에 따라 제출 의무가 있는 경우를 제외하고 제3자에게 제공하지 않습니다."}]},{"heading":"8. 고객지원 문의","blocks":[{"type":"p","text":"이용자가 고객지원에 문의하는 경우 문의 내용을 처리합니다. 답변받을 이메일 주소는 이용자가 직접 입력하고 별도로 동의하신 경우에만 함께 전송되며, 입력하지 않아도 문의를 보낼 수 있습니다."},{"type":"p","text":"해당 정보는 문의 확인과 답변을 위해서만 사용하며, 처리 완료 후 지체 없이 삭제합니다."},{"type":"p","text":"앱 안에서 보낸 의견은 서버에 저장되며, 저장된 날부터 24개월이 지나면 자동으로 삭제됩니다."},{"type":"p","text":"의견에는 기기 식별자와 함께 기기 모델, 운영체제, 국가와 언어 설정, 앱 버전이 담깁니다."}]},{"heading":"9. 오류 기록","blocks":[{"type":"p","text":"앱에서 오류가 발생하면 원인을 확인하기 위해 오류 내용과 발생 시점, 기기 식별자, 기기 모델과 운영체제, 앱 버전이 서버에 저장될 수 있습니다."},{"type":"p","text":"원인을 찾기 위해 오류 직전 앱 안에서 일어난 동작 기록(화면 이동, 상태 변화 등)이 함께 전송됩니다. 이 기록에는 이용자가 직접 작성한 글이 포함되지 않습니다."},{"type":"p","text":"하루에 저장하는 오류 건수에는 상한이 있으며, 이용자가 작성한 글은 포함되지 않습니다."},{"type":"p","text":"오류 기록도 저장된 날부터 24개월이 지나면 자동으로 삭제됩니다."}]},{"heading":"10. 이용자의 권리","blocks":[{"type":"p","text":"앱의 내정보 화면에서 초기화를 실행하시면 휴대폰에 저장된 내용이 즉시 삭제됩니다."},{"type":"p","text":"이용자는 문의 과정에서 제공한 정보, 자신이 공유한 활동, 또는 자신의 기기에서 저장된 이용 기록의 삭제를 요청할 수 있습니다."},{"type":"p","text":"이용 기록 삭제는 앱의 내정보 화면에서 「오류 신고 · 피드백 보내기」로 요청해 주세요. 요청에 기기 식별자가 함께 담기므로 따로 적어 보내실 것은 없습니다."},{"type":"p","text":"앱을 지우면 기기 식별자를 확인할 방법이 없어 어느 기록인지 찾지 못할 수 있습니다. 삭제를 원하시면 앱을 지우기 전에 요청해 주세요."},{"type":"p","text":"이미 지우신 뒤라면 아래 이메일로 알려주세요. 확인할 수 있는 범위에서 처리합니다."},{"type":"email","label":"이메일","address":"honeysaltlove@gmail.com"},{"type":"p","text":"공유 활동 삭제 요청 시 해당 활동을 확인할 수 있는 이름, 관련 링크 또는 설명이 필요할 수 있습니다."}]},{"heading":"11. 개인정보처리방침 변경","blocks":[{"type":"p","text":"이 방침이 변경되는 경우 시행 전에 앱 또는 홈페이지를 통해 안내합니다."}]},{"heading":"12. 문의","blocks":[{"type":"p","text":"개인정보 처리에 관한 문의와 공유 활동 삭제 요청은 고객지원 페이지에서 접수할 수 있습니다."},{"type":"link","to":"support","text":"고객지원 및 문의"}]}]}$json$, true, '2026-07-31T15:00:00Z', now(), now()),
('HONEY_DROPS', 'PRIVACY', 'en', '2026-08', $json${"title":"Honey Drops Privacy Policy","intro":"Honey Salt Love values the privacy of its users and explains below how information is handled in Honey Drops.","sections":[{"heading":"1. Records Created by Users","blocks":[{"type":"p","text":"Records you write yourself (emotion logs, thoughts, gratitude, goals, and the like) and user-created activities that have not been shared are stored on the user’s device."},{"type":"p","text":"The operator cannot access them."},{"type":"p","text":"Records stored on the device may be lost if the app is deleted or the device is changed, lost, or reset."}]},{"heading":"2. Information Stored on the Server to Improve the App","blocks":[{"type":"p","text":"To improve the app, Honey Drops stores daily usage records on the server together with a device identifier."},{"type":"p","text":"The following identifiers are used to distinguish devices. They do not include information that directly identifies a user, such as a name or contact details."},{"type":"list","items":["Device identifier (Android ID)","A random identifier created when the app first runs","Anonymous authentication identifier"]},{"type":"p","text":"The usage records stored alongside them are as follows."},{"type":"list","items":["The emotion selected that day","Honey Drops level and star count","Missions and activities completed","Items marked as helpful","Daily time spent","App version, language, and theme setting"]},{"type":"p","text":"Advertising identifiers are not collected, and records you write yourself (emotion logs, thoughts, gratitude, goals, and the like) are not sent to the server."},{"type":"p","text":"Information sent to the server is encrypted in transit."}]},{"heading":"3. Activities Shared by Users","blocks":[{"type":"p","text":"When a user chooses to share an activity on the activity registration screen, the following information is transmitted to the operator."},{"type":"list","items":["Activity name","Related link","Activity description","Related mission"]},{"type":"p","text":"Sharing an activity is optional; users can register and use an activity without sharing it."},{"type":"p","text":"Shared activities are used to review activities that may be recommended to other users and to improve the service, and users may request their deletion through the support page."}]},{"heading":"4. Purposes of Use","blocks":[{"type":"p","text":"Processed information is used only for the following purposes."},{"type":"list","items":["Reviewing service usage","Analyzing helpful activities","Reviewing and recommending shared activities","Improving features and services","Identifying errors"]}]},{"heading":"5. Retention and Deletion","blocks":[{"type":"p","text":"Usage records are stored by device identifier and date, and are deleted automatically 24 months after they are stored."},{"type":"p","text":"Running Reset in the app immediately deletes what is stored on your phone. Records stored on the server are not deleted immediately; their scheduled deletion date is moved to 24 months from the day you ran Reset, and they are deleted automatically on that date."},{"type":"p","text":"If you want them deleted sooner, please contact support."},{"type":"p","text":"Shared activities are retained for as long as necessary for service improvement and recommendations."},{"type":"p","text":"Information is deleted without delay when its purpose has been fulfilled or it is no longer needed."}]},{"heading":"6. Processing Entrusted to Others","blocks":[{"type":"p","text":"Honey Drops uses Google Firebase to operate the service and entrusts the following tasks to it."},{"type":"list","items":["Firebase Analytics — usage statistics","Cloud Firestore — storage of usage records","Firebase Crashlytics — error collection","Firebase Authentication — anonymous authentication"]},{"type":"p","text":"This information is stored on Google’s servers, which may be located outside your country."}]},{"heading":"7. Sharing with Third Parties","blocks":[{"type":"p","text":"Honey Salt Love does not sell usage information or provide it to third parties for advertising purposes."},{"type":"p","text":"Information is not provided to third parties unless disclosure is required by law."}]},{"heading":"8. Support Inquiries","blocks":[{"type":"p","text":"When a user contacts support, Honey Salt Love processes the inquiry. An email address for a reply is sent only if the user enters one and separately consents; an inquiry can be sent without providing one."},{"type":"p","text":"This information is used only to review and respond to the inquiry and is deleted without delay after the inquiry has been completed."},{"type":"p","text":"Feedback sent from within the app is stored on the server and is deleted automatically 24 months after it is stored."},{"type":"p","text":"Feedback is stored together with a device identifier, the device model, the operating system, the country and language settings, and the app version."}]},{"heading":"9. Error Records","blocks":[{"type":"p","text":"When an error occurs in the app, the error details, the time it occurred, a device identifier, the device model and operating system, and the app version may be stored on the server to determine the cause."},{"type":"p","text":"To help find the cause, a record of what happened inside the app just before the error (screen transitions, state changes, and the like) is sent as well. This record does not include anything the user has written."},{"type":"p","text":"The number of errors stored per day is capped, and records written by the user are not included."},{"type":"p","text":"Error records are also deleted automatically 24 months after they are stored."}]},{"heading":"10. User Rights","blocks":[{"type":"p","text":"Running Reset on the app’s Profile screen immediately deletes what is stored on your phone."},{"type":"p","text":"Users may request deletion of information provided through a support inquiry, of an activity they shared, or of the usage records stored for their device."},{"type":"p","text":"To delete usage records, please send the request from “Report a bug · Send feedback” on the app’s Profile screen. Your device identifier is included with the request, so there is nothing you need to write down."},{"type":"p","text":"Once the app is deleted, we have no way to look up the device identifier and may not be able to find the matching records. If you want them deleted, please send the request before deleting the app."},{"type":"p","text":"If you have already deleted it, email us at the address below and we will do what we can with the information available."},{"type":"email","label":"Email","address":"honeysaltlove@gmail.com"},{"type":"p","text":"To identify a shared activity for deletion, users may need to provide its name, related link, or description."}]},{"heading":"11. Changes to This Privacy Policy","blocks":[{"type":"p","text":"Changes to this policy will be announced through the app or website before they take effect."}]},{"heading":"12. Contact","blocks":[{"type":"p","text":"Privacy inquiries and requests to delete shared activities may be submitted through the support page."},{"type":"link","to":"support","text":"Support & Contact"}]}]}$json$, true, '2026-07-31T15:00:00Z', now(), now()),
('HONEY_DROPS', 'PRIVACY', 'ja', '2026-08', $json${"title":"ハニードロップス プライバシーポリシー","intro":"Honey Salt Love は利用者の情報を安全に保護し、ハニードロップス で扱う情報について以下のとおりご案内します。","sections":[{"heading":"1. 利用者が作成した記録","blocks":[{"type":"p","text":"利用者が自ら作成した記録（感情の記録、考え、感謝、目標など）および共有していない利用者の活動は、利用者の端末に保存されます。"},{"type":"p","text":"運営者はこれを確認することはできません。"},{"type":"p","text":"アプリを削除したり、端末を変更・紛失したりすると、端末に保存された記録が失われることがあります。"}]},{"heading":"2. アプリ改善のためにサーバーに保存する情報","blocks":[{"type":"p","text":"ハニードロップス は、アプリの改善のために、端末識別子とともに日付ごとの利用記録をサーバーに保存します。"},{"type":"p","text":"端末を区別するために以下の識別子を使用します。氏名や連絡先など、利用者を直接特定できる情報は含みません。"},{"type":"list","items":["端末識別子（Android ID）","アプリの初回起動時に生成したランダムな識別子","匿名認証の識別子"]},{"type":"p","text":"併せて保存される利用記録は以下のとおりです。"},{"type":"list","items":["その日に選んだ感情","ハニードロップス のレベルと星の数","実行したミッションと活動","「役に立った」と表示した項目","1日の利用時間","アプリのバージョン、言語、テーマ設定"]},{"type":"p","text":"広告識別子は収集せず、利用者が自ら書いた文章（感情の記録、考え、感謝、目標など）はサーバーに送信されません。"},{"type":"p","text":"サーバーに送信される情報は、通信経路上で暗号化されます。"}]},{"heading":"3. 利用者が共有した活動","blocks":[{"type":"p","text":"利用者が活動登録画面で共有を選択すると、以下の情報が運営者に送信されます。"},{"type":"list","items":["活動の名称","関連リンク","活動の説明","該当ミッション"]},{"type":"p","text":"活動の共有は任意であり、共有しなくても活動を登録して利用できます。"},{"type":"p","text":"共有された活動は、他の利用者に推薦する活動を検討し、サービスを改善するために使用され、削除を希望する場合はサポートページから依頼できます。"}]},{"heading":"4. 利用目的","blocks":[{"type":"p","text":"処理した情報は、以下の目的にのみ使用します。"},{"type":"list","items":["利用状況の把握","役に立つ活動の分析","共有された活動の検討と推薦","機能およびサービスの改善","不具合の確認"]}]},{"heading":"5. 保有および破棄","blocks":[{"type":"p","text":"利用記録は端末識別子と日付を基準に保存され、保存された日から24か月が経過すると自動的に削除されます。"},{"type":"p","text":"アプリで初期化を実行すると、スマートフォンに保存された内容は直ちに削除されます。サーバーに保存された記録は直ちには削除されず、削除予定日が初期化した日から24か月後に再設定され、その日に自動的に削除されます。"},{"type":"p","text":"それより前の削除をご希望の場合は、サポートまでご依頼ください。"},{"type":"p","text":"共有された活動は、サービスの改善および推薦に必要な期間、保管します。"},{"type":"p","text":"利用目的が達成された場合、または当該情報が不要になった場合は、遅滞なく削除します。"}]},{"heading":"6. 処理の委託","blocks":[{"type":"p","text":"ハニードロップス は、サービスの運営のために Google の Firebase を利用し、以下の業務を委託しています。"},{"type":"list","items":["Firebase Analytics — 利用統計","Cloud Firestore — 利用記録の保存","Firebase Crashlytics — 不具合の収集","Firebase Authentication — 匿名認証"]},{"type":"p","text":"当該情報は Google のサーバーに保存され、国外に所在する場合があります。"}]},{"heading":"7. 第三者への提供","blocks":[{"type":"p","text":"Honey Salt Love は、利用情報を販売したり、広告目的で提供したりしません。"},{"type":"p","text":"法令により提出義務がある場合を除き、第三者に提供しません。"}]},{"heading":"8. サポートへのお問い合わせ","blocks":[{"type":"p","text":"利用者がサポートに問い合わせる場合、問い合わせ内容を処理します。返信用のメールアドレスは、利用者がご自身で入力し、別途同意された場合にのみ送信されます。入力しなくてもお問い合わせを送ることができます。"},{"type":"p","text":"この情報は、問い合わせの確認と回答のためにのみ使用し、対応完了後は遅滞なく削除します。"},{"type":"p","text":"アプリ内から送られたご意見はサーバーに保存され、保存された日から24か月が経過すると自動的に削除されます。"},{"type":"p","text":"ご意見には、端末識別子とともに端末のモデル、OS、国と言語の設定、アプリのバージョンが含まれます。"}]},{"heading":"9. 不具合の記録","blocks":[{"type":"p","text":"アプリで不具合が発生した場合、原因を確認するために、不具合の内容と発生時刻、端末識別子、端末のモデルとOS、アプリのバージョンがサーバーに保存されることがあります。"},{"type":"p","text":"原因を特定するために、不具合の直前にアプリ内で起きた動作の記録（画面の移動、状態の変化など）も併せて送信されます。この記録に利用者が自ら書いた文章は含まれません。"},{"type":"p","text":"1日に保存する件数には上限があり、利用者が書いた文章は含まれません。"},{"type":"p","text":"不具合の記録も、保存された日から24か月が経過すると自動的に削除されます。"}]},{"heading":"10. 利用者の権利","blocks":[{"type":"p","text":"アプリのマイ情報画面で初期化を実行すると、スマートフォンに保存された内容は直ちに削除されます。"},{"type":"p","text":"利用者は、問い合わせの過程で提供した情報、自ら共有した活動、または自身の端末で保存された利用記録の削除を依頼できます。"},{"type":"p","text":"利用記録の削除は、アプリのマイ情報画面の「不具合の報告・フィードバック」からご依頼ください。ご依頼には端末識別子が含まれるため、ご自身で書き写していただく必要はありません。"},{"type":"p","text":"アプリを削除すると端末識別子を確認する方法がなくなり、該当する記録を見つけられない場合があります。削除をご希望の場合は、アプリを削除される前にご依頼ください。"},{"type":"p","text":"すでに削除された場合は、下記のメールアドレスまでご連絡ください。確認できる範囲で対応いたします。"},{"type":"email","label":"メール","address":"honeysaltlove@gmail.com"},{"type":"p","text":"共有した活動の削除を依頼する際には、その活動を特定できる名称、関連リンク、または説明が必要になることがあります。"}]},{"heading":"11. プライバシーポリシーの変更","blocks":[{"type":"p","text":"本ポリシーが変更される場合は、施行前にアプリまたはホームページを通じてお知らせします。"}]},{"heading":"12. お問い合わせ","blocks":[{"type":"p","text":"個人情報の取り扱いに関するお問い合わせおよび共有した活動の削除依頼は、サポートページから受け付けています。"},{"type":"link","to":"support","text":"サポート・お問い合わせ"}]}]}$json$, true, '2026-07-31T15:00:00Z', now(), now());
